import { test, expect } from '@playwright/test';

test.describe('Restore Archived Record', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully restore an archived record', async ({ page }) => {
    // Verify record list is visible
    const recordList = page.getByRole('region', { name: /record list/i });
    await expect(recordList).toBeVisible();

    // Locate and click on the archived record
    const archivedRecord = page.getByRole('button', { name: /archived record 123/i });
    await expect(archivedRecord).toBeVisible();
    await archivedRecord.click();

    // Verify record details page is displayed
    const recordDetails = page.getByRole('region', { name: /record details/i });
    await expect(recordDetails).toBeVisible();

    // Verify record is marked as archived
    const statusBadge = page.getByText('Archived');
    await expect(statusBadge).toBeVisible();

    // Click restore button
    const restoreButton = page.getByRole('button', { name: /restore/i });
    await expect(restoreButton).toBeVisible();
    await restoreButton.click();

    // Verify restore confirmation modal appears
    const confirmModal = page.getByRole('dialog', { name: /confirm restore/i });
    await expect(confirmModal).toBeVisible();

    // Click confirm restore
    const confirmRestoreButton = page.getByRole('button', { name: /confirm restore/i });
    await expect(confirmRestoreButton).toBeVisible();
    await confirmRestoreButton.click();

    // Verify success message
    const successMessage = page.getByText('Record restored successfully');
    await expect(successMessage).toBeVisible();

    // Verify status badge is updated to active
    const activeStatusBadge = page.getByText('Active');
    await expect(activeStatusBadge).toBeVisible();

    // Verify record is no longer in archive list
    const archiveList = page.getByRole('region', { name: /archived records/i });
    await expect(archiveList).not.toBeVisible();
  });

  test('should handle restore failure when record is locked', async ({ page }) => {
    // Locate and click on a locked archived record
    const lockedRecord = page.getByRole('button', { name: /locked record 456/i });
    await expect(lockedRecord).toBeVisible();
    await lockedRecord.click();

    // Verify record details page is displayed
    const recordDetails = page.getByRole('region', { name: /record details/i });
    await expect(recordDetails).toBeVisible();

    // Verify locked status is visible
    const lockedStatus = page.getByText('Locked');
    await expect(lockedStatus).toBeVisible();

    // Attempt to click restore button
    const restoreButton = page.getByRole('button', { name: /restore/i });
    await expect(restoreButton).toBeVisible();
    await restoreButton.click();

    // Verify error message appears
    const errorMessage = page.getByText('Cannot restore locked record');
    await expect(errorMessage).toBeVisible();

    // Verify restore confirmation modal does not appear
    const confirmModal = page.getByRole('dialog', { name: /confirm restore/i });
    await expect(confirmModal).not.toBeVisible();

    // Verify record status remains locked
    const lockedStatusAfterAttempt = page.getByText('Locked');
    await expect(lockedStatusAfterAttempt).toBeVisible();

    // Verify user can navigate away from the record details
    const backButton = page.getByRole('button', { name: /back to list/i });
    await expect(backButton).toBeVisible();
    await backButton.click();

    // Verify record list is visible again
    await expect(recordList).toBeVisible();
  });
});
